// Old file metadata remains readable; bubble layout uses complete content blocks.
const CANVAS_RATIOS=['16:9','4:3','1:1','3:4']
const bubbleContentLimit=height=>Math.min(480,Math.max(220,(Number.isFinite(height)?height:1000)-260))
function groupBubbleBlocks(blocks,limit=480){
  const groups=[];let current=[],used=0
  for(let index=0;index<blocks.length;index++){
    const block=blocks[index],height=Math.max(1,Number(block.height)||1),next=block.keepWithNext&&index+1<blocks.length?Math.max(1,Number(blocks[index+1].height)||1):0
    if(current.length&&(block.breakBefore||used+height+next>limit)&&groups.length<127){groups.push(current);current=[];used=0}
    current.push(index);used+=height
  }
  if(current.length)groups.push(current)
  return groups
}
function validCanvasMessage(data,id){
  return data?.type==='orivii:canvas'&&data.id===id&&Number.isInteger(data.height)&&data.height>0&&data.height<=1000000&&Number.isInteger(data.width)&&data.width>0&&data.width<=100000&&Number.isInteger(data.part)&&Number.isInteger(data.count)&&data.count>0&&data.count<=128&&data.part>=0&&data.part<data.count
}


function previewColorPolicy(){
  const clamp=(n,max=255)=>Math.max(0,Math.min(max,Number.isFinite(n)?n:0))
  const parse=value=>{
    if(typeof value!=='string')return null
    value=value.trim().toLowerCase();if(value==='transparent')return [0,0,0,0]
    if(/^#[\da-f]{3,4}$|^#[\da-f]{6}(?:[\da-f]{2})?$/.test(value)){
      let hex=value.slice(1);if(hex.length<5)hex=[...hex].map(c=>c+c).join('')
      return [0,2,4].map(i=>parseInt(hex.slice(i,i+2),16)).concat(hex.length===8?parseInt(hex.slice(6),16)/255:1)
    }
    const rgb=value.match(/^rgba?\((.*)\)$/),srgb=value.match(/^color\(srgb\s+(.+)\)$/),body=rgb?.[1]||srgb?.[1]
    if(!body)return null
    const fields=body.replace(/[,/]/g,' ').trim().split(/\s+/)
    if(fields.length<3||fields.length>4)return null
    const numbers=fields.map(parseFloat);if(!numbers.every(Number.isFinite))return null
    return numbers.slice(0,3).map((n,i)=>clamp(n*(srgb?255:fields[i].endsWith('%')?2.55:1))).concat(fields.length===4?clamp(numbers[3]/(fields[3].endsWith('%')?100:1),1):1)
  }
  const blend=(top,bottom)=>{
    const alpha=top[3]+bottom[3]*(1-top[3])
    return top.slice(0,3).map((n,i)=>alpha?(n*top[3]+bottom[i]*bottom[3]*(1-top[3]))/alpha:0).concat(alpha)
  }
  const css=color=>'rgb('+color.slice(0,3).map(n=>Math.round(clamp(n))).join(', ')+')'
  const luminance=color=>color.slice(0,3).map(n=>n/255).map(n=>n<=.04045?n/12.92:((n+.055)/1.055)**2.4).reduce((sum,n,i)=>sum+n*[.2126,.7152,.0722][i],0)
  const ratio=(a,b)=>{const x=luminance(blend(a,b)),y=luminance(b);return (Math.max(x,y)+.05)/(Math.min(x,y)+.05)}
  const black=[0,0,0,1],white=[255,255,255,1]
  const choose=(foreground,background,fallback)=>{
    const ink=parse(foreground),surface=parse(background)||white
    if(ink&&ratio(ink,surface)>=4.5)return null
    const candidates=[ink&&[...ink.slice(0,3),1],parse(fallback),black,white].filter(Boolean)
    return css(candidates.find(color=>ratio(color,surface)>=4.5)||candidates.sort((a,b)=>ratio(b,surface)-ratio(a,surface))[0])
  }
  const over=(foreground,background)=>css(blend(parse(foreground)||[0,0,0,0],parse(background)||white))
  const theme=(ink,surface,page)=>{
    const bg=over(surface,over(page,'#fff')),foreground=choose(ink,bg,'')||css(blend(parse(ink)||black,parse(bg)))
    return {ink:foreground,surface:bg}
  }
  return {choose,theme,over,contrast:(foreground,background)=>ratio(parse(foreground)||black,parse(background)||white)}
}

// This fixed program groups complete DOM blocks; it never clips or translates text.
function runPreviewCanvas(group,colorFactory){
  let config;try{config=JSON.parse(window.name)}catch{return}
  if(typeof config.id!=='string'||!config.id||!Number.isInteger(config.part)||config.part<0)return
  const flow=document.getElementById('orivii-preview-content');if(!flow)return
  const colors=colorFactory(),original=flow.cloneNode(true),limit=Math.min(720,Math.max(200,Number(config.limit)||480))
  let queued=false,last='',width=0
  function update(){
    queued=false
    flow.replaceChildren(...[...original.childNodes].map(node=>node.cloneNode(true)))
    const styles=[...flow.querySelectorAll('style')].map(node=>node.cloneNode(true)),units=[]
    const size=node=>{
      if(node.nodeType!==1){const range=document.createRange();range.selectNode(node);return range.getBoundingClientRect().height||1}
      const style=getComputedStyle(node);return node.getBoundingClientRect().height+(parseFloat(style.marginTop)||0)+(parseFloat(style.marginBottom)||0)
    }
    function collect(node,boundary=false){
      if(node.nodeType===3){if(node.textContent.trim())units.push({node,height:size(node),breakBefore:boundary});return}
      if(node.nodeType!==1||node.tagName==='STYLE')return
      const height=size(node),tag=node.tagName,semantic=tag==='SECTION'||node.classList.contains('card')||node.hasAttribute('data-bubble')
      if(tag==='TABLE'&&height>limit&&node.tBodies.length){
        const rows=[...node.tBodies].flatMap(body=>[...body.rows]),head=node.tHead,groups=group(rows.map(row=>({height:size(row)})),Math.max(80,limit-(head?size(head):0)-24))
        if(groups.length>1){
          const fragment=document.createDocumentFragment(),tables=groups.map((indices,index)=>{
            const table=node.cloneNode(false)
            for(const child of node.children)if(child.tagName==='COLGROUP'||child===head||(child.tagName==='CAPTION'&&index===0))table.append(child.cloneNode(true))
            const body=document.createElement('tbody');for(const i of indices)body.append(rows[i].cloneNode(true));table.append(body)
            if(index===groups.length-1&&node.tFoot)table.append(node.tFoot.cloneNode(true))
            fragment.append(table);return table
          })
          node.replaceWith(fragment);for(const table of tables)units.push({node:table,height:size(table),breakBefore:true});return
        }
      }
      const container=['MAIN','ARTICLE','DIV','SECTION','ASIDE','UL','OL'].includes(tag),children=[...node.childNodes].filter(child=>child.nodeType===1?child.tagName!=='STYLE':child.textContent?.trim())
      if(container&&children.length&&(!semantic||height>limit)){
        children.forEach((child,index)=>collect(child,(boundary||semantic)&&index===0));return
      }
      units.push({node,height,breakBefore:boundary||semantic,keepWithNext:/^H[2-6]$/.test(tag)})
    }
    for(const child of [...flow.childNodes])collect(child)
    const groups=group(units,limit),selected=groups[config.part]||[],range=document.createRange()
    if(selected.length){
      range.setStartBefore(units[selected[0]].node);range.setEndAfter(units[selected.at(-1)].node)
      const parent=range.commonAncestorContainer,fragment=range.cloneContents()
      if(parent!==flow&&parent.nodeType===1){const wrapper=parent.cloneNode(false);wrapper.append(fragment);flow.replaceChildren(...styles,wrapper)}
      else flow.replaceChildren(...styles,fragment)
    }else flow.replaceChildren(...styles)
    const rootStyle=getComputedStyle(document.documentElement),baseInk=rootStyle.getPropertyValue('--preview-ink').trim()||getComputedStyle(flow).color,surface=rootStyle.getPropertyValue('--preview-surface').trim()||'#fff'
    function repair(node,background){
      if(node.nodeType!==1||['STYLE','SCRIPT','TITLE','DEFS','CLIPPATH','MASK'].includes(node.tagName.toUpperCase()))return
      const style=getComputedStyle(node),backdrop=colors.over(style.backgroundColor,background),svg=node.namespaceURI==='http://www.w3.org/2000/svg',svgText=svg&&['text','tspan'].includes(node.localName)
      if((!svg||svgText)&&[...node.childNodes].some(child=>child.nodeType===3&&child.textContent.trim())){
        const value=svgText?style.fill:style.color,replacement=value==='none'&&svgText?null:colors.choose(value,backdrop,baseInk)
        if(replacement)node.style.setProperty(svgText?'fill':'color',replacement,'important')
      }
      for(const child of node.children)repair(child,backdrop)
    }
    repair(flow,surface)
    const height=Math.ceil(Math.max(1,flow.getBoundingClientRect().height,flow.scrollHeight))
    if(height>1000000)return
    const message={type:'orivii:canvas',id:config.id,part:config.part,count:Math.max(1,groups.length),height,width:Math.round(flow.clientWidth)},signature=JSON.stringify(message)
    if(last!==signature){last=signature;window.parent.postMessage(message,'*')}
    width=flow.clientWidth
  }
  const schedule=()=>{if(!queued){queued=true;queueMicrotask(update)}}
  window.addEventListener('message',event=>{if(event.source===window.parent&&event.data?.type==='orivii:measure'&&event.data.id===config.id){last='';schedule()}})
  window.addEventListener('resize',()=>{if(flow.clientWidth!==width)schedule()})
  if(window.ResizeObserver)new ResizeObserver(()=>{if(flow.clientWidth!==width)schedule()}).observe(flow)
  document.fonts?.ready.then(schedule);schedule()
}

const VISUAL_TEMPLATES={explain:{label:'图解',icon:'book-open'},compare:{label:'对比',icon:'columns-2'},metrics:{label:'指标',icon:'chart-column'},steps:{label:'流程',icon:'list-ordered'},chart:{label:'数据',icon:'chart-line'},explore:{label:'交互',icon:'sliders-horizontal'}}
const visualId=/^[a-z][a-z0-9_]{0,39}$/
const visualIcon=value=>{if(typeof value!=='string'||!Object.hasOwn(VISUAL_ICONS,value))throw new Error('图标名称无效。');return value}
const visualObject=(value,keys)=>{if(!value||typeof value!=='object'||Array.isArray(value)||Object.keys(value).some(key=>!keys.includes(key)))throw new Error('图文卡片字段无效。');return value}
const visualText=(value,max=500)=>{if(typeof value!=='string'||value.length>max)throw new Error('图文卡片文字过长或格式无效。');return value}
const visualNumber=value=>{if(typeof value!=='number'||!Number.isFinite(value)||Math.abs(value)>1e12)throw new Error('图文卡片数值无效。');return value}
const visualArray=(value,max)=>{if(!Array.isArray(value)||!value.length||value.length>max)throw new Error('图文卡片项目数量无效。');return value}
const visualName=value=>{if(typeof value!=='string'||!visualId.test(value)||['constructor','prototype','__proto__'].includes(value))throw new Error('图文卡片标识无效。');return value}
const visualScalar=(value,known)=>{
  if(typeof value==='string')return visualText(value)
  if(typeof value==='number')return visualNumber(value)
  visualObject(value,['ref']);visualName(value.ref);if(!known.has(value.ref))throw new Error('图文卡片引用尚未定义。');return {ref:value.ref}
}
const visualNumeric=(value,known)=>{if(typeof value==='string')throw new Error('图表数值须为数字或控件引用。');return visualScalar(value,known)}

function validateVisualSpec(input){
  if(JSON.stringify(input).length>100000)throw new Error('图文卡片内容过大。')
  visualObject(input,['version','title','description','demo','template','ratio','controls','calculations','blocks','sources'])
  if(input.version!==1)throw new Error('图文卡片版本无效。')
  const result={version:1,title:visualText(input.title,120),blocks:[]},known=new Set()
  if(input.template!==undefined){if(!Object.hasOwn(VISUAL_TEMPLATES,input.template))throw new Error('图文模板无效。');result.template=input.template}
  if(input.ratio!==undefined){if(!CANVAS_RATIOS.includes(input.ratio))throw new Error('画布比例无效。');result.ratio=input.ratio}
  if(input.description!==undefined)result.description=visualText(input.description,600)
  if(input.demo!==undefined){if(typeof input.demo!=='boolean')throw new Error('演示标记无效。');result.demo=input.demo}
  if(input.controls!==undefined)result.controls=visualArray(input.controls,8).map(control=>{
    visualObject(control,['id','type','label','value','min','max','step','options'])
    const id=visualName(control.id),label=visualText(control.label,80)
    if(known.has(id))throw new Error('图文卡片标识重复。')
    let next
    if(control.type==='slider'){
      const min=visualNumber(control.min),max=visualNumber(control.max),value=visualNumber(control.value),step=visualNumber(control.step??1)
      if(max<=min||value<min||value>max||step<=0||step>max-min)throw new Error('滑块范围无效。')
      next={id,label,type:'slider',min,max,step,value}
    }else if(control.type==='toggle'){
      if(typeof control.value!=='boolean')throw new Error('开关值无效。');next={id,label,type:'toggle',value:control.value}
    }else if(control.type==='select'){
      const options=visualArray(control.options,8).map(option=>{visualObject(option,['label','value']);return {label:visualText(option.label,60),value:visualNumber(option.value)}})
      if(!options.some(option=>option.value===control.value))throw new Error('选择值无效。')
      next={id,label,type:'select',value:control.value,options}
    }else throw new Error('控件类型无效。')
    known.add(id);return next
  })
  if(input.calculations!==undefined)result.calculations=visualArray(input.calculations,12).map(calculation=>{
    visualObject(calculation,['id','op','inputs']);const id=visualName(calculation.id)
    if(known.has(id)||!['add','subtract','multiply','divide','power'].includes(calculation.op))throw new Error('计算项无效。')
    const inputs=visualArray(calculation.inputs,8).map(value=>visualNumeric(value,known))
    if(['subtract','divide','power'].includes(calculation.op)&&inputs.length!==2)throw new Error('计算项参数数量无效。')
    known.add(id);return {id,op:calculation.op,inputs}
  })
  result.blocks=visualArray(input.blocks,12).map(block=>{
    const type=block.type
    if(type==='text'){visualObject(block,['type','text']);return {type,text:visualText(block.text,4000)}}
    if(type==='metrics'){
      visualObject(block,['type','items']);return {type,items:visualArray(block.items,12).map(item=>{
        visualObject(item,['label','value','unit','hint','digits','icon']);const next={label:visualText(item.label,100),value:visualScalar(item.value,known)}
        if(item.icon!==undefined)next.icon=visualIcon(item.icon)
        for(const key of ['unit','hint'])if(item[key]!==undefined)next[key]=visualText(item[key],key==='hint'?300:40)
        if(item.digits!==undefined){if(!Number.isInteger(item.digits)||item.digits<0||item.digits>8)throw new Error('小数位数无效。');next.digits=item.digits}return next
      })}
    }
    if(type==='cards'){
      visualObject(block,['type','columns','items']);if(block.columns!==undefined&&![1,2,3].includes(block.columns))throw new Error('卡片列数无效。')
      return {type,columns:block.columns||2,items:visualArray(block.items,8).map(item=>{visualObject(item,['title','text','icon']);return {title:visualText(item.title,120),text:visualText(item.text,2000),...(item.icon!==undefined?{icon:visualIcon(item.icon)}:{})}})}
    }
    if(type==='table'){
      visualObject(block,['type','columns','rows']);const columns=visualArray(block.columns,8).map(value=>visualText(value,100))
      const rows=visualArray(block.rows,40).map(row=>{if(!Array.isArray(row)||row.length!==columns.length)throw new Error('表格列数不一致。');return row.map(value=>visualScalar(value,known))})
      return {type,columns,rows}
    }
    if(type==='chart'){
      visualObject(block,['type','kind','title','labels','series','unit'])
      if(!['bar','line'].includes(block.kind))throw new Error('图表类型无效。')
      const labels=visualArray(block.labels,40).map(value=>visualText(value,80)),series=visualArray(block.series,4).map(row=>{
        visualObject(row,['name','values']);if(!Array.isArray(row.values)||row.values.length!==labels.length)throw new Error('图表数据长度不一致。')
        return {name:visualText(row.name,80),values:row.values.map(value=>visualNumeric(value,known))}
      })
      return {type,kind:block.kind,title:visualText(block.title??'',120),labels,series,unit:visualText(block.unit??'',40)}
    }
    if(type==='flow'){
      visualObject(block,['type','items']);return {type,items:visualArray(block.items,8).map(item=>{visualObject(item,['title','text','icon']);return {title:visualText(item.title,120),text:visualText(item.text??'',600),...(item.icon!==undefined?{icon:visualIcon(item.icon)}:{})}})}
    }
    if(type==='svg'){visualObject(block,['type','source','caption']);return {type,source:visualText(block.source,40000),caption:visualText(block.caption??'',300)}}
    throw new Error('图文卡片组件类型无效。')
  })
  if(input.sources!==undefined)result.sources=visualArray(input.sources,8).map(source=>visualText(source,500))
  return result
}

function visualValues(spec,controls={}){
  const values=new Map()
  for(const control of spec.controls||[]){
    const candidate=controls[control.id]??control.value
    let value=control.value
    if(control.type==='toggle')value=typeof candidate==='boolean'?candidate:control.value
    else if(Number.isFinite(candidate))value=control.type==='slider'?Math.max(control.min,Math.min(control.max,candidate)):control.options.some(option=>option.value===candidate)?candidate:control.value
    values.set(control.id,typeof value==='boolean'?Number(value):value)
  }
  const resolve=value=>value&&typeof value==='object'?values.get(value.ref):value
  for(const c of spec.calculations||[]){
    const args=c.inputs.map(resolve);let value=null
    if(args.every(x=>typeof x==='number'&&Number.isFinite(x))){
      if(c.op==='add')value=args.reduce((a,b)=>a+b,0)
      if(c.op==='multiply')value=args.reduce((a,b)=>a*b,1)
      if(c.op==='subtract')value=args[0]-args[1]
      if(c.op==='divide'&&args[1]!==0)value=args[0]/args[1]
      if(c.op==='power'&&Math.abs(args[1])<=12)value=args[0]**args[1]
    }
    values.set(c.id,Number.isFinite(value)&&Math.abs(value)<=1e12?value:null)
  }
  return {values,resolve}
}
function visualSummary(spec){
  const {resolve}=visualValues(spec),lines=[(spec.demo?'演示图示：':'图示：')+spec.title,spec.description||'']
  for(const block of spec.blocks){
    if(block.type==='text')lines.push(block.text)
    if(block.type==='metrics')lines.push(...block.items.map(item=>item.label+'：'+(resolve(item.value)??'—')+(item.unit||'')))
    if(block.type==='cards'||block.type==='flow')lines.push(...block.items.map(item=>item.title+'：'+item.text))
    if(block.type==='table')lines.push(block.columns.join(' / '),...block.rows.map(row=>row.map(resolve).join(' / ')))
    if(block.type==='chart')lines.push(block.title+' '+block.labels.join(' / '),...block.series.map(row=>row.name+'：'+row.values.map(resolve).join(', ')+' '+block.unit))
    if(block.type==='svg')lines.push(block.caption||'SVG 图示')
  }
  return lines.filter(Boolean).join('\n').slice(0,8000)
}
function filePreviewKind(file){if(file.preview==='visual'||/\.orivii\.json$/i.test(file.name))return 'visual';if(/\.html?$/i.test(file.name))return 'html';if(/\.svg$/i.test(file.name))return 'svg';return null}

